mapper.select:
select id, name, user_id, image,
       dish_id     as goodsId,
       setmeal_id  as comboId,
       dish_flavor as goodsSpec,
       number, amount, create_time
from shopping_cart


        and user_id = #{userId}


        and setmeal_id = #{comboId}


        and dish_id = #{goodsId}


        and dish_flavor = #{goodsSpec}
